    domestic_expected_return = next((item['number_value'] for item in value_list if item['header1'] == '2019' and item['header3'] == 'Domestic'), None)
    international_expected_return = next((item['number_value'] for item in value_list if item['header1'] == '2019' and item['header3'] == 'International'), None)

    if domestic_discount_rate is None or international_discount_rate is None:
