def run(value_list):
    # Filter the value list for defined contribution schemes and defined benefit schemes
    defined_contribution_schemes = [item for item in value_list if item['category'] == 'Defined contribution schemes']
    defined_benefit_schemes = [item for item in value_list if item['category'] == 'Defined benefit schemes']

    # Calculate the average of 2019 defined contribution schemes
    avg_2019_contribution = sum(item['number_value'] for item in defined_contribution_schemes if item['header1'] == '2019 € million') / len([item for item in defined_contribution_schemes if item['header1'] == '2019 € million'])

    # Calculate the average of 2019 defined benefit schemes
    avg_2019_benefit = sum(item['number_value'] for item in defined_benefit_schemes if item['header1'] == '2019 € million') / len([item for item in defined_benefit_schemes if item['header1'] == '2019 € million'])

    # Calculate the difference between the two averages
    difference = avg_2019_contribution - avg_2019_benefit

    # Return the result as a tuple with the correct scale
    if abs(difference) < 1000:
        return (round(difference, 2), '')
    elif abs(difference) < 1000000:
        return (round(difference / 1000, 2), 'thousand')
    elif abs(difference) < 1000000000:
        return (round(difference / 1000, 2), 'million')
    elif abs(difference) < 1000000000000:
        return (round(difference / 1000, 2), 'billion')
    else:
        return (round(difference / 1000, 2), 'billion')

