def run(value_list):
    total_2018 = 0
    total_2019 = 0
    count_2018 = 0
    count_2019 = 0

    for item in value_list:
        if item['category'] == 'Outstanding at end of period' and item['header2'] == '2018':
            total_2018 += item['number_value']
            count_2018 += 1
        elif item['category'] == 'Outstanding at end of period' and item['header2'] == '2019':
            total_2019 += item['number_value']
