            scale = 'million'
        else:
            scale = 'billion'
        return (round(average, 2), scale)

def run(value_list):
    # Filter the list to get the 'outstanding at start of period' values
    outstanding_start = [item['number_value'] for item in value_list if item['category'] == 'Outstanding at start of period']

    # Get the values for 2018 and 2019
    start_2018 = outstanding_start[0]
    start_2019 = outstanding_start[1]

    # Calculate the percentage increase
    if start_2018 == 0:
        percentage_increase = 0
    else:
        percentage_increase = ((start_2019 - start_2018) / start_2018) * 100

    # Format the result
    if percentage_increase < 0:
        number = f"-{abs(percentage_increase):.2f}"
        scale = 'percent'
    else:
        number = f"{percentage_increase:.2f}"
        scale = 'percent'

    return (number, scale)

