    us_government_obligations_unrealized_gain = 0

    for item in value_list:
        if item['header3'] == 'As of December 31, 2018':
            if item['category'] == 'U.S. government obligations':
                us_government_obligations_unrealized_gain_2018 += item['number_value']
            total_unrealized_gain_2018 += item['number_value']
        elif item['header3'] == 'As of December 31, 2019':
            if item['category'] == 'U.S. government obligations':
                us_government_obligations_unrealized_gain += item['number_value']
            total_unrealized_gain += item['number_value']

    total_unrealized_gain = round(total_unrealized_gain_2018 + total_unrealized_gain, 2)
    us_government_obligations_unrealized_gain = round(us_government_obligations_unrealized_gain_2018 + us_government_obligations_unrealized_gain, 2)

    if total_unrealized_gain == 0:
        return (0.0, '')
    else:
        percentage = round((us_government_obligations_unrealized_gain / total_unrealized_gain) * 100, 2)
        if percentage < 1:
            return (percentage, 'percent')
        elif percentage < 1000:
            return (percentage / 1000, 'thousand')
        elif percentage < 1000000:
            return (percentage / 1000, 'million')
        elif percentage < 1000000000:
            return (percentage / 1000, 'billion')
        else:
            return (percentage / 1000000, 'billion')

