        average_basic = (total_basic_2018 / count_2018 + total_basic_2019 / count_2019) / 2
        if average_basic < 1:
            return (round(average_basic * 1000000, 2), 'million')
        elif average_basic < 1000:
            return (round(average_basic, 2), 'thousand')
        else:
            return (round(average_basic / 1000, 2), 'million')

