def run(value_list):
    sep = ['thousand', 'million', 'billion', 'percent']
    def convert_scale(scale):
        if scale in sep:
            return scale
        elif scale == '':
            return ''
        else:
            return scale + ' ' + scale.capitalize()

    sep_index = 0
    for item in value_list:
        if item['header2'] == 'September 29, 2019':
            high_price = item['number_value']
            low_price = next((item['number_value'] for item in value_list if item['header2'] == 'September 29, 2019' and item['category'] == 'Low'), None)
            if low_price is not None:
                low_price = round(low_price, 2)
                return (round(high_price - low_price, 2), convert_scale(''))
            else:
                return (round(high_price, 2), convert_scale(''))
        sep_index += 1

    return (0, '')

