    financing_2019 = next((item for item in value_list if item['category'] == 'Financing activities' and item['header2'] == '2019'), None)

    if financing_2018 is None or financing_2019 is None:
        return (0.0, '')

    cash_provided_2018 = financing_2018['number_value']
    cash_provided_2019 = financing_2019['number_value']

    percentage_change = ((cash_provided_2019 - cash_provided_2018) / cash_provided_2018) * 100

    if abs(percentage_change) < 1e-6:
        return (0.0, '')
    elif abs(percentage_change) < 1e-3:
        return (round(percentage_change, 1), 'thousand')
    elif abs(percentage_change) < 1e-1:
        return (round(percentage_change, 2), 'million')
    elif abs(percentage_change) < 1e-2:
        return (round(percentage_change, 2), 'billion')
    else:
        return (round(percentage_change, 2), 'percent')

