def run(value_list):
    total = 0
    count = 0
    for item in value_list:
        if item['category'] == 'Products and licensing costs' and (item['header1'] == '2018' or item['header1'] == '2019'):
            total += item['number_value']
            count += 1
    if count == 0:
        return (0, '')
    average = round(total / count, 2)
    scale = ''
    if average % 1000 != 0:
        scale = 'thousand'
    elif average % 1000000 != 0:
        scale = 'million'
    elif average % 1000000000 != 0:
        scale = 'billion'
    elif average % 100 != 0:
        scale = 'hundred'
    elif average % 10 != 0:
        scale = 'ten'
    return (average, scale)

