def run(value_list):
    total_goodwill_2018 = 0
    total_goodwill_2019 = 0
    total_goodwill_network_2018 = 0
    total_goodwill_network_2019 = 0

    for item in value_list:
        if item['category'] == 'Goodwill acquired':
            if item['header1'] == 'Network Software & Systems':
                if item['number_value'] > 0:
                    total_goodwill_network_2018 += item['number_value']
                else:
                    total_goodwill_network_2019 += item['number_value']
            else:
                if item['number_value'] > 0:
                    total_goodwill_2018 += item['number_value']
                else:
                    total_goodwill_2019 += item['number_value']

    total_goodwill_2018 = round(total_goodwill_2018, 2)
    total_goodwill_2019 = round(total_goodwill_2019, 2)
    total_goodwill_network_2018 = round(total_goodwill_network_2018, 2)
    total_goodwill_network_2019 = round(total_goodwill_network_2019, 2)

    if total_goodwill_2018 == 0 and total_goodwill_2019 == 0:
        return (0, '')
    elif total_goodwill_2018 == 0:
        return (total_goodwill_network_2019, 'billion')
    elif total_goodwill_2019 == 0:
        return (total_goodwill_network_2018, 'billion')
    elif total_goodwill_2018 == total_goodwill_2019:
        return (0, '')
    else:
        percentage_change = ((total_goodwill_network_2019 - total_goodwill_network_2018) / total_goodwill_network_2018) * 100
        if percentage_change < 0:
            return (round(percentage_change, 2), 'percent')
        else:
            return (round(percentage_change, 2), 'percent')

