def run(value_list):
    total_2018 = sum(item['number_value'] for item in value_list if item['category'] == 'Wages and salaries' or item['category'] == 'Social security' or item['category'] == 'Pension expenses' or item['category'] == 'Share-based payment expenses' or item['category'] == 'Restructuring expenses')
    total_2019 = sum(item['number_value'] for item in value_list if item['category'] == 'Wages and salaries' or item['category'] == 'Social security' or item['category'] == 'Pension expenses' or item['category'] == 'Share-based payment expenses' or item['category'] == 'Restructuring expenses')
    change = round((total_2019 - total_2018) / 1000, 2)
    if change < 0:
        scale = 'thousand'
    elif change > 0:
        scale = 'thousand'
    else:
        scale = ''
    return (change, scale)

