def run(value_list):
    telecommunication_maintenance_2018 = next((item for item in value_list if item['category'] == 'Telecommunication - Maintenance' and item['header1'] == '2018'), None)
    telecommunication_maintenance_2019 = next((item for item in value_list if item['category'] == 'Telecommunication - Maintenance' and item['header1'] == '2019'), None)

    if telecommunication_maintenance_2018 is None or telecommunication_maintenance_2019 is None:
        return (0, '')

    increase = telecommunication_maintenance_2019['number_value'] - telecommunication_maintenance_2018['number_value']
    scale = 'thousand' if increase >= 1000 else 'million' if increase >= 1000000 else 'billion' if increase >= 1000000000 else ''
    return (round(increase, 2), scale)

def run(value_list):
    telecommunication_installation = [item['number_value'] for item in value_list if item['category'] == 'Telecommunication - Installation']
    if not telecommunication_installation:
        return (0, '')
    average_installation = sum(telecommunication_installation) / len(telecommunication_installation)
    scale = {1: '', 10: 'thousand', 100: 'million', 1000: 'billion'}[1 if average_installation < 1000 else 10 if average_installation < 1000000 else 1000]
    return (round(average_installation, 2), scale)

def run(value_list):
    total_marine_revenue = sum(item['number_value'] for item in value_list if item['category'] == 'Total Marine Services segment revenue')
    average_revenue = total_marine_revenue / len([item for item in value_list if item['category'] == 'Total Marine Services segment revenue'])
    return (round(average_revenue, 2), '' if average_revenue % 1 == 0 else 'k' if average_revenue % 1000 == 0 else 'M' if average_revenue % 1000000 == 0 else 'B')
